function excerptText(result, data, query) {
  //console.log("Query", query);
  const page = data.find(p => p.url === result.ref);
  const content = page.content.toLowerCase();
  //const query = content.split(' ').find(term => term);
  
  if (!query) return '';

  const index = content.indexOf(query);
  if (index === -1) return '';

  const start = Math.max(0, index - 20);
  const end = Math.min(content.length, index + 60);
  const excerpt = content.substring(start, end);
  const cleaned_excerpt = excerpt.replace(/<\/?[^>]+(>|$)/g, " ");
  //console.log("Cleaned excerpt", cleaned_excerpt)
  return '...' + cleaned_excerpt + '...';
}

function excerptHeader(result, data) {
  
  const content = data.find(p => p.url === result.ref).content
  //console.log("Content", content);
  var start = content.indexOf('>') + 1;
  var end = content.indexOf('</h1>');
  if (end === -1) {
    end = content.length;
  }
  var header = content.substring(start, end);
  //console.log("Header", header);
  return header
}
